<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/commerce_v1230.php';$s=sk1230_settings();$sum=sk1230_cart_summary();if(!$sum['items']){header('Location: /cart-v1230.php');exit;}$u=sk1230_user();$addresses=sk1230_addresses();$member=sk1230_active_membership();$wallet=sk1230_wallet();$err='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();$r=sk1230_checkout($_POST);header('Location: /order-track-v1230.php?token='.rawurlencode($r['token']).'&placed=1');exit;}}catch(Throwable $e){$err=$e->getMessage();}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout — ShahkotPK</title><link rel="stylesheet" href="/assets/commerce-v1230.css?v=1230"></head><body><main class="co1230"><header class="co-top"><div><a class="co-brand" href="/cart-v1230.php">← Back to Cart</a><div class="co-kicker">SECURE LOCAL CHECKOUT</div><h1>Place your order</h1><p>One checkout can create separate seller fulfillment groups while you track everything under one order number.</p></div><?php if($member):?><div class="pill">✦ <?=sk1230_h($member['plan_name'])?> active</div><?php endif;?></header><?php if($err):?><div class="notice bad"><?=sk1230_h($err)?></div><?php endif;?><div class="grid"><form method="post" class="panel form-grid"><input type="hidden" name="_csrf" value="<?=sk1230_h(csrf_token())?>"><label>Your name<input required name="customer_name" maxlength="140" value="<?=sk1230_h($u['name']??'')?>"></label><label>Phone / WhatsApp<input required name="customer_phone" maxlength="60" value="<?=sk1230_h($u['phone']??'')?>"></label><label class="wide">Email (optional)<input type="email" name="customer_email" maxlength="190" value="<?=sk1230_h($u['email']??'')?>"></label><?php if($addresses):?><label class="wide">Saved address<select id="savedAddress"><option value="">Enter a new address below</option><?php foreach($addresses as $a):?><option data-name="<?=sk1230_h($a['recipient_name'])?>" data-phone="<?=sk1230_h($a['phone'])?>" data-address="<?=sk1230_h($a['address_line'])?>" data-area="<?=sk1230_h($a['area'])?>"><?=sk1230_h($a['label'].' — '.$a['address_line'])?></option><?php endforeach;?></select></label><?php endif;?><label>Fulfillment<select name="fulfillment_type" id="fulfillment"><option value="delivery">Home Delivery</option><option value="pickup">Pickup from shops</option></select></label><label>Area<input name="area" id="area" maxlength="180" placeholder="e.g. Bilal Town"></label><label class="wide">Delivery address<textarea name="address_text" id="address" rows="2" maxlength="700" placeholder="House / street / landmark"></textarea></label><label>Address label<input name="address_label" maxlength="60" value="Home"></label><label class="check"><input type="checkbox" name="save_address" value="1" <?=$u?'checked':''?>> Save this address</label><?php if($s['scheduled_orders']):?><label class="wide">Schedule delivery/pickup (optional)<input type="datetime-local" name="scheduled_for"></label><?php endif;?><label>Coupon code<input name="coupon_code" maxlength="60" placeholder="Optional"></label><label>Payment method<select name="payment_method"><?php if($s['cod_enabled']):?><option value="cod">Cash on Delivery</option><?php endif;?><?php if($s['advance_enabled']):?><option value="advance">Advance / Manual Payment</option><?php endif;?><?php if($s['wallet_enabled']&&sk1230_uid()>0):?><option value="wallet">ShahkotPK Wallet (<?=sk1230_money($wallet)?>)</option><?php endif;?></select></label><label class="wide">Order notes<textarea name="customer_notes" rows="2" maxlength="1200" placeholder="Delivery instructions, color/variant note, etc."></textarea></label><button class="btn primary wide">Place Order Securely</button></form><aside class="panel checkout-box"><h2>Cart total</h2><?php foreach($sum['groups'] as $g):?><div class="summary-line"><span><?=sk1230_h($g['business_name'])?></span><b><?=sk1230_money($g['subtotal'])?></b></div><?php endforeach;?><div class="summary-line total"><span>Products</span><b><?=sk1230_money($sum['subtotal'])?></b></div><p style="color:#64748b;font-size:13px">Final delivery fee, coupon discount and member free-delivery benefit are calculated when you place the order. Advance payment orders stay “Awaiting Payment” until confirmed.</p></aside></div></main><script>const s=document.getElementById('savedAddress');if(s)s.addEventListener('change',()=>{const o=s.options[s.selectedIndex];if(!o.value&&!o.dataset.address)return;document.querySelector('[name=customer_name]').value=o.dataset.name||'';document.querySelector('[name=customer_phone]').value=o.dataset.phone||'';document.getElementById('address').value=o.dataset.address||'';document.getElementById('area').value=o.dataset.area||''});document.getElementById('fulfillment').addEventListener('change',e=>{document.getElementById('address').required=e.target.value==='delivery'});</script></body></html>
